package com.yuewei.plm.module.partner;

import java.util.*;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import static com.yuewei.plm.module.partner.PartnerValues.*;

@Service @RequiredArgsConstructor
public class PartnerCustomerService {
 private final PartnerStore store;
 @org.springframework.beans.factory.annotation.Autowired private com.yuewei.plm.module.inventory.maintenance.FoundationObjectReferences references;
 public List<Map<String,Object>> all(){store.access.requireDomesticView();store.access.requirePermission("customer:view");return store.jdbc.queryForList(query()+" where c.deleted_flag=0 and "+store.access.visibleSqlClause("customer","c.customer_id")+" order by c.updated_at desc");}
 public Map<String,Object> page(Map<String,String> q){
  store.access.requireDomesticView();store.access.requirePermission("customer:view");String where="c.deleted_flag=0 and "+store.access.visibleSqlClause("customer","c.customer_id");List<Object> args=new ArrayList<>();if(!text(q.get("keyword")).isEmpty()){where+=" and (c.customer_name ilike ? or c.customer_code ilike ? or c.contact_name ilike ?)";for(int i=0;i<3;i++)args.add("%"+q.get("keyword")+"%");}if(!text(q.get("status")).isEmpty()){where+=" and c.status=?";args.add(q.get("status"));}if(!text(q.get("type")).isEmpty()){where+=" and c.customer_type=?";args.add(q.get("type"));}long total=store.jdbc.queryForObject("select count(*) from plm_customer c where "+where,Long.class,args.toArray()),page=Math.max(1,number(q.getOrDefault("page","1")));args.add(30);args.add((page-1)*30);return Map.of("content",store.jdbc.queryForList(query()+" where "+where+" order by c.updated_at desc limit ? offset ?",args.toArray()),"totalElements",total,"page",page,"size",30);}
 private String query(){return "select c.customer_id as \"customerId\",c.customer_code as \"customerCode\",c.customer_name as \"customerName\",coalesce(c.customer_short_name,'') as \"customerShortName\",coalesce(c.customer_type,'unknown') as \"customerType\",coalesce(c.country_code,'') as \"countryCode\",coalesce(c.contact_name,'') as \"contactName\",coalesce(c.contact_phone,'') as \"contactPhone\",coalesce(c.contact_email,'') as \"contactEmail\",c.status,c.version,c.profile_data::text as profile,c.updated_at as \"updatedAt\" from plm_customer c";}
 public Map<String,Object> detail(long id){
  store.access.requireDomesticView();store.access.requirePermission("customer:view");store.access.requireCustomer(id);
  var rows=store.jdbc.queryForList(query()+" where c.customer_id=? and c.deleted_flag=0",id);require(!rows.isEmpty(),"客户不存在");var d=rows.get(0);d.putAll(decode(store.json,d.remove("profile")));d.put("relatedOrders",store.jdbc.queryForList("select code as \"orderCode\",name as \"orderTitle\",status,record_id as \"recordId\" from plm_partner_record p where p.customer_id=? and p.deleted_flag=0 and "+store.access.visibleSqlClause("partner","p.record_id"),id));d.put("operationLogs",store.jdbc.queryForList("select created_at as time,created_by as operator,action,'info' as level from plm_partner_event where customer_id=? order by event_id desc",id));return d;
 }
 @Transactional public Map<String,Object> save(Long id,Map<String,Object> input){
  store.access.requireDomesticView();store.access.requirePermission(id==null?"customer:create":"customer:edit");
  String name=required(input.get("customerName"),"客户名称"),type=text(input.getOrDefault("customerType","unknown")),status=text(input.getOrDefault("status","draft"));
  require(Set.of("company","person","unknown").contains(type),"客户类型无效");require(Set.of("draft","active","inactive").contains(status),"客户状态无效");require(!status.equals("active")||!type.equals("unknown"),"启用前请明确客户类型");
  String request=required(input.get("requestId"),"提交标识");require(request.length()<=80,"提交标识过长");boolean creating=id==null;if(creating){Long repeated=store.created("customer",request);if(repeated!=null)return detail(repeated);}
  Map<String,Object> before=new LinkedHashMap<>();if(id!=null){store.access.requireCustomer(id);var repeats=store.jdbc.queryForList("select data::text from plm_partner_event where customer_id=? and actor_id=? and request_id=? and action='customer_save'",id,store.access.actorId(),request);if(!repeats.isEmpty()){var prior=decode(store.json,repeats.get(0).get("data"));require(signature(store.json,input).equals(signature(store.json,prior.get("after"))),"提交标识已用于其他保存");return detail(id);}var versions=store.jdbc.queryForList("select version from plm_customer where customer_id=? and deleted_flag=0 for update",id);require(!versions.isEmpty(),"客户不存在");if(!input.containsKey("version")||number(input.get("version"))!=number(versions.get(0).get("version")))throw new com.yuewei.plm.common.exception.BusinessException(40901,"客户已变化，请刷新后核对");before=detail(id);if(!text(before.get("status")).equals(status)&&(status.equals("inactive")||text(before.get("status")).equals("inactive")))required(input.get("reason"),"状态更改原因");}
  var actor=store.access.actor();Map<String,Object> profile=new LinkedHashMap<>();for(String key:List.of("address","sourceType","ownerUserName","website","websiteCustomerId","remark"))profile.put(key,text(input.get(key)));profile.put("ownerUserName",actor.displayName());
  if(id==null)id=store.jdbc.queryForObject("insert into plm_customer(customer_code,customer_name,customer_type,status,version,created_by,updated_by) values(?,?,? ,?,0,?,?) returning customer_id",Long.class,"C-"+UUID.randomUUID().toString().substring(0,12),name,type,status,actor.username(),actor.username());
  if(creating)store.remember("customer",request,id);
  store.jdbc.update("update plm_customer set customer_name=?,customer_short_name=?,customer_type=?,country_code=?,contact_name=?,contact_phone=?,contact_email=?,status=?,version=version+1,profile_data=?::jsonb,updated_at=now(),updated_by=? where customer_id=?",name,text(input.get("customerShortName")),type,text(input.get("countryCode")),text(input.get("contactName")),text(input.get("contactPhone")),text(input.get("contactEmail")),status,encode(store.json,profile),actor.username(),id);
  if(store.access.isPilot())store.jdbc.update("insert into plm_pilot_scope(user_id,entity_type,entity_id) values(?,'customer',?) on conflict do nothing",actor.userId(),id);
  store.jdbc.update("insert into plm_partner_event(customer_id,action,data,request_id,created_by,actor_id) values(?,'customer_save',?::jsonb,?,?,?)",id,encode(store.json,Map.of("before",before,"after",input)),request,actor.displayName(),actor.userId());
  store.audit.logRequired(com.yuewei.plm.module.operationlog.service.OperationLogCreateCommand.builder().action("CUSTOMER_SAVE").businessType("CUSTOMER").businessId(Long.toString(id)).detailJson(encode(store.json,Map.of("requestId",request,"before",before,"after",input))).build(),actor);
  return detail(id);
 }
 @Transactional(readOnly=true) public Map<String,Object> references(long id){store.access.requireDomesticView();store.access.requirePermission("customer:view");store.access.requireCustomer(id);return inspection(customer(id,false));}
 private Map<String,Object> customer(long id,boolean lock){var rows=store.jdbc.queryForList("select * from plm_customer c where customer_id=? and ("+store.access.visibleSqlClause("customer","c.customer_id")+")"+(lock?" for update":""),id);require(rows.size()==1,"客户不存在或未获授权");return rows.get(0);}
 private Map<String,Object> result(Map<String,Object> r){return Map.of("id",r.get("customer_id"),"name",r.get("customer_name"),"code",r.get("customer_code"),"status",r.get("status"),"version",r.get("version"),"deleted",number(r.get("deleted_flag"))!=0);}
 private Map<String,Object> inspection(Map<String,Object> r){var usage=references.inspect("customer",number(r.get("customer_id")),text(r.get("customer_code")));var out=new LinkedHashMap<>(result(r));boolean editable=store.access.hasPermission("customer:edit"),deleted=number(r.get("deleted_flag"))!=0;out.put("canDelete",editable&&!deleted&&!Boolean.TRUE.equals(usage.get("used")));out.put("canDeactivate",editable&&!deleted&&!text(r.get("status")).equals("inactive"));out.put("canActivate",editable&&!deleted&&text(r.get("status")).equals("inactive")&&!text(r.get("customer_type")).equals("unknown"));out.put("references",usage.get("references"));out.put("hasRestrictedReferences",usage.get("hasRestrictedReferences"));if(Boolean.TRUE.equals(usage.get("used")))out.put("blockedReason","存在业务或历史引用，不能删除，可停用并保留记录");return out;}
 @Transactional public Map<String,Object> lifecycle(long id,String action,Map<String,Object> input){
  store.access.requireDomesticView();store.access.requirePermission("customer:view");store.access.requirePermission("customer:edit");require(Set.of("delete","deactivate","activate").contains(action),"客户操作无效");String request=required(input.get("requestId"),"提交标识"),reason=required(input.get("reason"),"本次操作原因");require(request.length()<=80&&reason.length()<=2000,"提交标识或原因过长");var before=customer(id,true);String signature=signature(store.json,Map.of("action",action,"version",number(input.get("version")),"reason",reason));
  var repeats=store.jdbc.queryForList("select action,data::text from plm_partner_event where customer_id=? and actor_id=? and request_id=? order by event_id",id,store.access.actorId(),request);if(!repeats.isEmpty()){var prior=repeats.get(0);var data=decode(store.json,prior.get("data"));require(("customer_"+action).equals(prior.get("action"))&&signature.equals(data.get("signature")),"提交标识已用于其他客户操作");return map(data.get("after"));}
  require(number(before.get("deleted_flag"))==0,"客户已删除，不能恢复或更新");if(input.get("version")==null||number(input.get("version"))!=number(before.get("version")))throw new com.yuewei.plm.common.exception.BusinessException(40901,"客户已变化，请刷新引用清单后核对");
  var check=inspection(before);String capability=switch(action){case "delete"->"canDelete";case "deactivate"->"canDeactivate";default->"canActivate";};if(!Boolean.TRUE.equals(check.get(capability)))throw new com.yuewei.plm.common.exception.BusinessException(40901,text(check.getOrDefault("blockedReason","客户状态已变化；启用前须明确客户类型")));
  if(action.equals("delete"))store.jdbc.update("update plm_customer set deleted_flag=1,version=version+1,updated_by=?,updated_at=now() where customer_id=?",store.access.actor().username(),id);else store.jdbc.update("update plm_customer set status=?,version=version+1,updated_by=?,updated_at=now() where customer_id=?",action.equals("deactivate")?"inactive":"active",store.access.actor().username(),id);
  var after=result(customer(id,false));var data=Map.of("signature",signature,"reason",reason,"before",result(before),"after",after);store.jdbc.update("insert into plm_partner_event(customer_id,action,data,request_id,created_by,actor_id) values(?,?,?::jsonb,?,?,?)",id,"customer_"+action,encode(store.json,data),request,store.access.actor().displayName(),store.access.actorId());store.audit.logRequired(com.yuewei.plm.module.operationlog.service.OperationLogCreateCommand.builder().action("CUSTOMER_"+action.toUpperCase(Locale.ROOT)).businessType("CUSTOMER").businessId(Long.toString(id)).detailJson(encode(store.json,data)).build(),store.access.actor());return after;
 }
}
